function validate(input) {
  const [content] = input;
  if (typeof content !== 'string' || content.length > 10000) return 'content must be text of at most 10,000 characters.';
  if (!/^[a-z \n]*$/.test(content)) return 'Use only lowercase letters, spaces and line breaks.';
  const counts = new Map();
  for (const word of content.split(/[ \n]+/)) if (word) counts.set(word, (counts.get(word) || 0) + 1);
  if (new Set(counts.values()).size !== counts.size) return 'Each distinct word must occur a different number of times.';
  return null;
}

