function wordFrequency(content) {
  // Collect words character by character, then repeatedly pick the most frequent word left.
  const words = [];
  let current = '';
  for (const ch of content + ' ') {
    if (ch >= 'a' && ch <= 'z') current += ch;
    else if (current) { words.push(current); current = ''; }
  }
  const distinct = [];
  for (const word of words) if (!distinct.includes(word)) distinct.push(word);
  const tally = distinct.map((word) => [word, words.filter((w) => w === word).length]);
  const out = [];
  while (tally.length) {
    let best = 0;
    for (let i = 1; i < tally.length; i++) if (tally[i][1] > tally[best][1]) best = i;
    const [[word, count]] = tally.splice(best, 1);
    out.push(word + ' ' + count);
  }
  return out.join('\n');
}

