function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const kinds = size === 'small' ? pick(6) : 20 + pick(21);
  const seen = new Set(), words = [];
  while (words.length < kinds) {
    const length = 1 + pick(size === 'small' ? 3 : 7);
    let word = '';
    for (let i = 0; i < length; i++) word += String.fromCharCode(97 + pick(size === 'small' ? 4 : 26));
    if (!seen.has(word)) { seen.add(word); words.push(word); }
  }
  // Distinct counts keep every frequency unique, as the problem guarantees.
  const counts = Array.from({ length: kinds }, (_, i) => i + 1);
  for (let i = counts.length - 1; i > 0; i--) { const j = pick(i + 1); [counts[i], counts[j]] = [counts[j], counts[i]]; }
  const bag = [];
  words.forEach((word, i) => { for (let c = 0; c < counts[i]; c++) bag.push(word); });
  for (let i = bag.length - 1; i > 0; i--) { const j = pick(i + 1); [bag[i], bag[j]] = [bag[j], bag[i]]; }
  const gap = () => { const r = rand(); return r < 0.6 ? ' ' : r < 0.8 ? '\n' : r < 0.9 ? '  ' : ' \n '; };
  let content = rand() < 0.2 ? ' ' : '';
  bag.forEach((word, i) => { content += (i ? gap() : '') + word; });
  if (rand() < 0.5) content += rand() < 0.5 ? '\n' : '  ';
  return [content];
}
